solution.solution.cpp:
#include <algorithm>
#include <cmath>
#include <limits>
#include <vector>

struct Vector3 { float x, y, z; };
struct Box { Vector3 min, max; };
struct Target { Box box; int hp; };
struct Keys { bool forward{ false }, back{ false }, left{ false }, right{ false }, jump{ false }; };

struct Player
{
    Vector3 feet{ 0, 0, 0 };
    Vector3 vel{ 0, 0, 0 };
    float yaw{ 0 }, pitch{ 0 };
    bool onGround{ false };
};

namespace
{
    constexpr float Rad{ 3.14159265358979f / 180.0f };
    constexpr float Half{ 0.3f }, Height{ 1.8f };

    Box body(const Player& p)
    {
        return { { p.feet.x - Half, p.feet.y, p.feet.z - Half }, { p.feet.x + Half, p.feet.y + Height, p.feet.z + Half } };
    }

    bool overlap(const Box& a, const Box& b)
    {
        return a.min.x < b.max.x && b.min.x < a.max.x && a.min.y < b.max.y && b.min.y < a.max.y && a.min.z < b.max.z && b.min.z < a.max.z;
    }

    float get(const Vector3& v, int a) { return a == 0 ? v.x : a == 1 ? v.y : v.z; }

    // Distance along the ray to the box, or infinity for a miss.
    float rayBox(Vector3 pos, Vector3 dir, const Box& b)
    {
        float tmin{ 0 }, tmax{ std::numeric_limits<float>::infinity() };
        for (int a{ 0 }; a < 3; ++a)
        {
            const float p{ get(pos, a) }, d{ get(dir, a) }, lo{ get(b.min, a) }, hi{ get(b.max, a) };
            if (d == 0) { if (p < lo || p > hi) return std::numeric_limits<float>::infinity(); continue; }
            float t1{ (lo - p) / d }, t2{ (hi - p) / d };
            if (t1 > t2) std::swap(t1, t2);
            tmin = std::max(tmin, t1);
            tmax = std::min(tmax, t2);
            if (tmin > tmax) return std::numeric_limits<float>::infinity();
        }
        return tmin;
    }
}

void look(Player& p, float mouseDx, float mouseDy, float sensitivity)
{
    p.yaw = std::fmod(p.yaw - mouseDx * sensitivity, 360.0f);
    if (p.yaw < 0) p.yaw += 360.0f;
    if (p.yaw >= 360.0f) p.yaw -= 360.0f;
    p.pitch = std::clamp(p.pitch - mouseDy * sensitivity, -89.0f, 89.0f);
}

Vector3 eye(const Player& p) { return { p.feet.x, p.feet.y + 1.6f, p.feet.z }; }

Vector3 viewDirection(const Player& p)
{
    const float y{ p.yaw * Rad }, pt{ p.pitch * Rad };
    return { std::cos(pt) * std::sin(y), std::sin(pt), std::cos(pt) * std::cos(y) };
}

void walk(Player& p, const std::vector<Box>& walls, const Keys& k, float dt)
{
    const float y{ p.yaw * Rad };
    const float fw{ static_cast<float>(k.forward) - static_cast<float>(k.back) };
    const float rt{ static_cast<float>(k.right) - static_cast<float>(k.left) };
    float wx{ std::sin(y) * fw - std::cos(y) * rt }, wz{ std::cos(y) * fw + std::sin(y) * rt };
    const float len{ std::sqrt(wx * wx + wz * wz) };
    if (len > 0) { wx /= len; wz /= len; }
    p.vel.x = wx * 5.0f;
    p.vel.z = wz * 5.0f;
    if (k.jump && p.onGround) p.vel.y = 7.0f;
    p.vel.y -= 20.0f * dt;

    // x
    p.feet.x += p.vel.x * dt;
    {
        float stop{ p.feet.x };
        bool hit{ false };
        for (const Box& w : walls)
        {
            if (!overlap(body(p), w)) continue;
            if (p.vel.x > 0) { stop = std::min(stop, w.min.x - Half); hit = true; }
            else if (p.vel.x < 0) { stop = std::max(stop, w.max.x + Half); hit = true; }
        }
        if (hit) { p.feet.x = stop; p.vel.x = 0; }
    }
    // z
    p.feet.z += p.vel.z * dt;
    {
        float stop{ p.feet.z };
        bool hit{ false };
        for (const Box& w : walls)
        {
            if (!overlap(body(p), w)) continue;
            if (p.vel.z > 0) { stop = std::min(stop, w.min.z - Half); hit = true; }
            else if (p.vel.z < 0) { stop = std::max(stop, w.max.z + Half); hit = true; }
        }
        if (hit) { p.feet.z = stop; p.vel.z = 0; }
    }
    // y
    p.feet.y += p.vel.y * dt;
    bool landed{ false };
    {
        float stop{ p.feet.y };
        bool hit{ false };
        for (const Box& w : walls)
        {
            if (!overlap(body(p), w)) continue;
            if (p.vel.y < 0) { stop = std::max(stop, w.max.y); hit = true; landed = true; }
            else if (p.vel.y > 0) { stop = std::min(stop, w.min.y - Height); hit = true; }
        }
        if (hit) { p.feet.y = stop; p.vel.y = 0; }
    }
    p.onGround = landed;
}

int shoot(const Player& p, const std::vector<Box>& walls, std::vector<Target>& targets)
{
    const Vector3 from{ eye(p) }, dir{ viewDirection(p) };
    float best{ std::numeric_limits<float>::infinity() };
    int hit{ -1 };
    for (const Box& w : walls)
    {
        const float t{ rayBox(from, dir, w) };
        if (t < best) { best = t; hit = -1; }
    }
    for (std::size_t i{ 0 }; i < targets.size(); ++i)
    {
        if (targets[i].hp <= 0) continue;
        const float t{ rayBox(from, dir, targets[i].box) };
        if (t < best) { best = t; hit = static_cast<int>(i); }
    }
    if (hit >= 0) --targets[static_cast<std::size_t>(hit)].hp;
    return hit;
}

unitTests:
const float dt = 1.0f / 60;
const Box floorBox{ { -20, -1, -20 }, { 20, 0, 20 } };
Player onFloor() { Player p; p.onGround = true; return p; }
TEST("looking around") {
    Player p; look(p, -900, 0, 0.1f); CHECK_NEAR(p.yaw, 90.0, 1e-3); look(p, 1800, 0, 0.1f); CHECK_NEAR(p.yaw, 270.0, 1e-3);
    look(p, 0, -10000, 0.1f); CHECK_NEAR(p.pitch, 89.0, 1e-4); look(p, 0, 5000, 0.1f); CHECK_NEAR(p.pitch, -89.0, 1e-4);
}
TEST("falling onto the floor") { Player p; p.feet.y = 0.5f; for (int i = 0; i < 60; ++i) walk(p, { floorBox }, {}, dt); CHECK_NEAR(p.feet.y, 0.0, 1e-5); CHECK(p.onGround); }
TEST("walking where you look") {
    Player p = onFloor(); Keys k; k.forward = true; for (int i = 0; i < 60; ++i) walk(p, { floorBox }, k, dt);
    CHECK_NEAR(p.feet.z, 5.0, 1e-3); CHECK_NEAR(p.feet.x, 0.0, 1e-4);
    Player q = onFloor(); look(q, -900, 0, 0.1f); for (int i = 0; i < 30; ++i) walk(q, { floorBox }, k, dt); CHECK_NEAR(q.feet.x, 2.5, 1e-3);
    Player r = onFloor(); Keys d; d.forward = true; d.right = true; for (int i = 0; i < 60; ++i) walk(r, { floorBox }, d, dt);
    CHECK_NEAR(r.feet.x, -3.5355, 1e-3); CHECK_NEAR(r.feet.z, 3.5355, 1e-3);
}
TEST("walls stop you") {
    const std::vector<Box> walls{ floorBox, { { -10, 0, 3 }, { 10, 3, 4 } }, { { -4, 0, -10 }, { -3, 3, 10 } } };
    Player p = onFloor(); Keys k; k.forward = true; for (int i = 0; i < 120; ++i) walk(p, walls, k, dt); CHECK_NEAR(p.feet.z, 2.7, 1e-4); CHECK(p.onGround);
    Player q = onFloor(); Keys r; r.right = true; for (int i = 0; i < 120; ++i) walk(q, walls, r, dt); CHECK_NEAR(q.feet.x, -2.7, 1e-4);
}
TEST("jumping") {
    Player p = onFloor(); Keys k; k.jump = true; walk(p, { floorBox }, k, dt); CHECK(!p.onGround);
    float top = p.feet.y; for (int i = 0; i < 60; ++i) { walk(p, { floorBox }, {}, dt); top = std::max(top, p.feet.y); }
    CHECK_NEAR(top, 1.1667, 0.01); CHECK(p.onGround); CHECK_NEAR(p.feet.y, 0.0, 1e-5);
}
TEST("a low ceiling") {
    const std::vector<Box> walls{ floorBox, { { -20, 2.5f, -20 }, { 20, 3, 20 } } };
    Player p = onFloor(); Keys k; k.jump = true; walk(p, walls, k, dt);
    float top = p.feet.y; for (int i = 0; i < 60; ++i) { walk(p, walls, {}, dt); top = std::max(top, p.feet.y); }
    CHECK_NEAR(top, 0.7, 1e-4); CHECK(p.onGround);
}
TEST("shooting") {
    std::vector<Target> t{ { { { -0.5f, 1, 4 }, { 0.5f, 2, 5 } }, 2 }, { { { -0.5f, 1, 8 }, { 0.5f, 2, 9 } }, 1 } };
    Player p;
    CHECK_EQ(shoot(p, {}, t), 0); CHECK_EQ(t[0].hp, 1); CHECK_EQ(shoot(p, {}, t), 0); CHECK_EQ(t[0].hp, 0);
    CHECK_EQ(shoot(p, {}, t), 1); CHECK_EQ(t[1].hp, 0); CHECK_EQ(shoot(p, {}, t), -1);
    std::vector<Target> u{ { { { -0.5f, 1, 4 }, { 0.5f, 2, 5 } }, 2 } };
    CHECK_EQ(shoot(p, { { { -1, 0, 2 }, { 1, 3, 2.5f } } }, u), -1); CHECK_EQ(u[0].hp, 2);
    Player up; up.pitch = 45; CHECK_EQ(shoot(up, {}, u), -1);
}

